+
+/**
+ * @return array{
+ *     normalized_cwd: ?string,
+ *     primary_solo_process_id: ?int,
+ *     timestamp: mixed,
+ * }
+ */
+function codexCandidateContext(string $path): array
+{
+    $candidateCwd = null;
+    $timestamp = null;
+    $baseInstructionsIdentity = null;
+    $firstUserIdentity = null;
+    $firstUserMessageSeen = false;
+
+    foreach (jsonl($path) as $row) {
+        if (($row['type'] ?? null) === 'session_meta') {
+            $payload = $row['payload'] ?? [];
+
+            if ($candidateCwd === null && is_string($payload['cwd'] ?? null)) {
+                $candidateCwd = $payload['cwd'];
+            }
+
+            if ($timestamp === null && array_key_exists('timestamp', $payload)) {
+                $timestamp = $payload['timestamp'];
+            }
+
+            if ($baseInstructionsIdentity === null) {
+                $base = $payload['base_instructions'] ?? '';
+                $baseText = is_array($base) && isset($base['text'])
+                    ? (string) $base['text']
+                    : (is_string($base) ? $base : '');
+                $baseInstructionsIdentity = soloProcessIdFromText($baseText);
+            }
+
+            continue;
+        }
+
+        if ($firstUserMessageSeen || ($row['type'] ?? null) !== 'response_item') {
+            continue;
+        }
+
+        $payload = $row['payload'] ?? [];
+
+        if (($payload['type'] ?? null) !== 'message' || ($payload['role'] ?? null) !== 'user') {
+            continue;
+        }
+
+        $firstUserMessageSeen = true;
+        $firstUserIdentity = soloProcessIdFromUserIdentityMarker(extractText($payload['content'] ?? ''));
+    }
+
+    return [
+        'normalized_cwd' => normalizeCodexCwd($candidateCwd),
+        'primary_solo_process_id' => $baseInstructionsIdentity ?? $firstUserIdentity,
+        'timestamp' => $timestamp,
+    ];
+}
+
+function soloProcessIdFromText(string $text): ?int
+{
+    if (preg_match('/Solo process ID:\s*(\d+)\b/', $text, $matches) !== 1) {
+        return null;
+    }
+
+    return (int) $matches[1];
+}
+
+function soloProcessIdFromUserIdentityMarker(string $text): ?int
+{
+    if (preg_match('/(?:^|\R)\s*Solo process ID:\s*(\d+)\b/', $text, $matches) !== 1) {
+        return null;
+    }
+
+    return (int) $matches[1];
+}
+
+function normalizeCodexCwd(?string $cwd): ?string
+{
+    if ($cwd === null || trim($cwd) === '') {
+        return null;
+    }
+
+    $resolved = realpath($cwd);
+
+    if ($resolved !== false) {
+        return $resolved;
+    }
+
+    $isAbsolute = str_starts_with($cwd, '/');
+    $segments = [];
+
+    foreach (preg_split('~/+~', $cwd) ?: [] as $segment) {
+        if ($segment === '' || $segment === '.') {
+            continue;
+        }
+
+        if ($segment === '..') {
+            if ($segments !== [] && end($segments) !== '..') {
